// Portable read-only CI wrapper; production source, records and databases remain untouched.
import assert from 'node:assert/strict';import path from 'node:path';import {execFileSync} from 'node:child_process';
const root=path.resolve(process.argv[2]||process.cwd()),head=process.argv[3]||'HEAD',baseline=process.argv[4]||'b12e20c1b6d856a021898a0c1c9221b30393a221';
const exact=execFileSync('git',['rev-parse',head],{cwd:root,encoding:'utf8'}).trim();const output=execFileSync(process.execPath,['.github/scripts/compare_p1s_recommendation.mjs',baseline,exact],{cwd:root,encoding:'utf8',maxBuffer:1<<28});const result=JSON.parse(output),summary={head:exact,baseline,clock:result.now,weekGeneratedAt:result.weekGeneratedAt,conditions:{}};
for(const flag of ['withSightings','withoutSightings']){const a=result.out[baseline]?.[flag],b=result.out[exact]?.[flag];assert.ok(a&&b,flag+' comparator output');assert.equal(b.siteCount,190);assert.equal(b.candidates,176);assert.equal(b.top.length,10);assert.equal(typeof b.allCandidateSignature,'string');assert.equal(a.allCandidateSignature,b.allCandidateSignature,flag+' full candidate signature');const tie=e=>[e.score,e.rank,e.bonus].join('|');assert.deepEqual(b.top.map(tie),a.top.map(tie),flag+' top10 position-wise score/rank/bonus (Issue #9 B may only swap fully tied candidates)');assert.equal(b.unsafe.length,0);summary.conditions[flag]={siteCount:b.siteCount,candidates:b.candidates,signature:b.allCandidateSignature,allSignatureEqual:true,top10ScoreRankBonusExact:true,top10IdsChanged:b.top.map((e,i)=>e.id===a.top[i].id?null:[a.top[i].id,e.id]).filter(Boolean),unsafeCount:0};}
{const x=result.out[baseline].syntheticNullScores,y=result.out[exact].syntheticNullScores,tie=e=>[e.score,e.rank].join('|');assert.equal(y.candidates,x.candidates,'invalid raw scores: same candidates');assert.equal(y.nulledSites,x.nulledSites,'invalid raw scores: same excluded sites');assert.deepEqual(y.top.map(tie),x.top.map(tie),'invalid raw scores remain excluded (score/rank positions)');}console.log(JSON.stringify(summary,null,2));
